import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  /** Render prop receives the error and a reset callback — use this instead of a static fallback when you need a retry button. */
  fallback?: (error: Error, reset: () => void) => ReactNode;
  /** Optional external logger (e.g. Sentry). Called after console.error. */
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  componentStack: string | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, componentStack: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    console.error("[ErrorBoundary]", error, info.componentStack);
    this.setState({ componentStack: info.componentStack ?? null });
    this.props.onError?.(error, info);
  }

  reset = (): void => {
    this.setState({ error: null, componentStack: null });
  };

  render(): ReactNode {
    const { error } = this.state;

    if (error) {
      if (this.props.fallback) {
        return this.props.fallback(error, this.reset);
      }

      return <DefaultFallback error={error} onRetry={this.reset} />;
    }

    return this.props.children;
  }
}

function DefaultFallback({
  error,
  onRetry,
}: {
  error: Error;
  onRetry: () => void;
}) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.heading}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={onRetry} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles = {
  container: {
    padding: "1rem",
    border: "1px solid #f87171",
    borderRadius: "0.375rem",
    background: "#fff1f2",
    color: "#991b1b",
  },
  heading: { margin: "0 0 0.5rem", fontSize: "1rem" },
  message: {
    whiteSpace: "pre-wrap" as const,
    fontSize: "0.875rem",
    marginBottom: "1rem",
  },
  button: {
    padding: "0.375rem 0.75rem",
    border: "1px solid #f87171",
    borderRadius: "0.25rem",
    background: "white",
    color: "#991b1b",
    cursor: "pointer",
  },
} as const;
